class Solution { private lateinit var nums:IntArray;private lateinit var answer:IntArray;private lateinit var graph:Array<MutableList<Int>>;private lateinit var stacks:Array<java.util.ArrayDeque<IntArray>>;private fun gcd(a:Int,b:Int):Int=if(b==0)a else gcd(b,a%b);private fun dfs(node:Int,parent:Int,depth:Int){var bestDepth=-1;for(value in 1..50)if(gcd(nums[node],value)==1&&stacks[value].isNotEmpty()&&stacks[value].last[1]>bestDepth){bestDepth=stacks[value].last[1];answer[node]=stacks[value].last[0]};stacks[nums[node]].addLast(intArrayOf(node,depth));for(next in graph[node])if(next!=parent)dfs(next,node,depth+1);stacks[nums[node]].removeLast()};fun getCoprimes(nums:IntArray,edges:Array<IntArray>):IntArray{this.nums=nums;answer=IntArray(nums.size){-1};graph=Array(nums.size){mutableListOf()};stacks=Array(51){java.util.ArrayDeque()};for(edge in edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0])};dfs(0,-1,0);return answer} }
